**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <algorithm>
#include <iomanip>
using namespace std;

struct Lot {
    string numer, miasto;
    int minuty, opoznienie;
};

int main() {
    ifstream plik("loty.txt");
    vector<Lot> loty;
    string nr, mst;
    int godz, opz;
    while (plik >> nr >> mst >> godz >> opz) {
        loty.push_back({nr, mst, godz * 60 + opz, opz});
    }

    cout << "a) Rzeczywiste godziny odlotu:" << endl;
    for (auto &l : loty) {
        cout << "   " << l.numer << " " << l.miasto << ": "
             << setw(2) << setfill('0') << l.minuty / 60 << ":"
             << setw(2) << setfill('0') << l.minuty % 60 << endl;
    }

    sort(loty.begin(), loty.end(), [](const Lot &a, const Lot &b) {
        return a.minuty < b.minuty;
    });

    cout << endl << "b) Harmonogram (wg rzeczywistej godziny):" << endl;
    for (auto &l : loty) {
        cout << "   " << setw(2) << setfill('0') << l.minuty / 60 << ":"
             << setw(2) << setfill('0') << l.minuty % 60
             << " " << l.numer << " -> " << l.miasto << endl;
    }

    int opoznione = 0;
    for (auto &l : loty) {
        if (l.opoznienie > 0) opoznione++;
    }
    cout << endl << "c) Opoznionych lotow: " << opoznione << " ("
         << fixed << setprecision(1) << (opoznione * 100.0 / loty.size()) << "%)" << endl;
    return 0;
}
```

